INPUT_DIR = '/inputs'
import json
from decimal import Decimal, ROUND_HALF_UP
from datetime import date

def load(name):
    try:
        with open(f"{INPUT_DIR}/{name}", encoding="utf-8") as fh:
            return json.load(fh)
    except FileNotFoundError:
        return None

def dec(v):
    if v is None:
        return None
    if isinstance(v, str) and v.strip().lower() == "unreadable":
        return None
    try:
        return Decimal(str(v))
    except Exception:
        return None

def cents(d):
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

def parse_date(s):
    if not isinstance(s, str):
        return None
    try:
        return date.fromisoformat(s)
    except Exception:
        return None

bill = load("bill.json") or {}
tariff = load("tariff.json") or {}
history = load("history.json")

subtotal = None
vat = None
total = None

consumption = dec(bill.get("consumption_kl"))
tiers = tariff.get("water_tiers")
vat_rate = dec(tariff.get("vat_rate"))
fixed = tariff.get("fixed_charges")

if consumption is not None and isinstance(tiers, list) and vat_rate is not None and isinstance(fixed, list):
    lines = []
    ok = True
    for t in tiers:
        f = dec(t.get("from_kl"))
        to = t.get("to_kl")
        rate = dec(t.get("rate_per_kl"))
        if f is None or rate is None:
            ok = False
            break
        upper = None if to is None else dec(to)
        if to is not None and upper is None:
            ok = False
            break
        if upper is None:
            band = consumption - f
        else:
            band = min(consumption, upper) - f
        if band < 0:
            band = Decimal(0)
        lines.append(cents(band * rate))
    if ok:
        for fc in fixed:
            amt = dec(fc.get("amount"))
            if amt is None:
                ok = False
                break
            lines.append(cents(amt))
    if ok:
        subtotal = sum(lines, Decimal(0))
        vat = cents(subtotal * vat_rate)
        total = subtotal + vat

normal_kl = None
implied_kl = None

period_days = None
outage_days = None
supplied_days = None

bp = bill.get("billing_period") or {}
start = parse_date(bp.get("start"))
end = parse_date(bp.get("end"))
if start is not None and end is not None and end >= start:
    period_days = (end - start).days + 1

if isinstance(history, dict):
    acct_match = history.get("account_number") == bill.get("account_number")
    prev = history.get("previous_bills")
    normal_avg = None
    if acct_match and isinstance(prev, list):
        vals = []
        for p in prev:
            c = dec(p.get("consumption_kl"))
            if c is not None:
                vals.append(c)
        if len(vals) >= 2:
            normal_avg = sum(vals, Decimal(0)) / Decimal(len(vals))
            normal_kl = normal_avg.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)
    if start is not None and end is not None and end >= start:
        log = history.get("outage_log")
        if isinstance(log, list):
            dates = set()
            for e in log:
                if e.get("supply") == "none":
                    d = parse_date(e.get("date"))
                    if d is not None and start <= d <= end:
                        dates.add(d)
            outage_days = len(dates)
            if period_days is not None:
                supplied_days = period_days - outage_days
                if normal_avg is not None and period_days > 0:
                    implied = normal_avg * Decimal(supplied_days) / Decimal(period_days)
                    implied_kl = implied.quantize(Decimal("0.1"), rounding=ROUND_HALF_UP)

out = {
    "subtotal": None if subtotal is None else str(cents(subtotal)),
    "vat": None if vat is None else str(cents(vat)),
    "total": None if total is None else str(cents(total)),
    "normal_kl": None if normal_kl is None else str(normal_kl),
    "period_days": period_days,
    "outage_days": outage_days,
    "supplied_days": supplied_days,
    "implied_kl": None if implied_kl is None else str(implied_kl),
}
print(json.dumps(out))
